style.css:
@-moz-document domain("inside.amazon.com") {
body, #top, .amz_Blurb, .amz_Blurb P, .amz_currentBlurbHeadline, .ms-bodyareaframe, div#amz_mainContent, div.amz_section, div.amz_summary, td.ms-bodyareacell {
    background: #222 !important;
    color: #ddd !important;
  }
  
  td.rightColumn, div.breadcrumb, .breadcrumbCurrent, .amz_publishLine, .level-band, #amz_leftnav {
    background: #333 !important;
    color: #ddd !important;
  }
  
  li.selected {
    background: #444 !important;
  }
  
  li.selected > a.amz_LeftNavSelected, div.amz_topLink {
    background: #555 !important;
  }
  
  div.ms-WPBody > p > span, .ms-rteThemeForeColor-2-0, .ms-rteElement-P > span, .ms-rteFontSize-2, .ms-rteFontSize-2 span {
    color: #ddd !important;
  }
    
  td.rightColumn strong, small {
    color: #ddd !important;
  }
  
  .ms-WPHeader {
    background: #222 !important;
  }
  
  .ms-WPHeader td {
    border-color: #888 !important;
  }
  
  td.rightColumn a:link, div#amz_mainContent a:link, div.amz_summary a:link, div.breadcrumb a:link, .breadcrumbCurrent a:link, a.ms-sitemapdirectional, #amz_leftnav .menu-item-text, .ms-SPLink a:link {
    color: #0af !important;
  }
  
  .amz_section img {
    background-color: #eee !important;
  }
}
